const csv = items[0].json.data ?? items[0].json.body ?? items[0].json;
const texto = typeof csv === 'string' ? csv : JSON.stringify(csv);
const linhas = texto.split(/\r?\n/).map(linha => linha.trim()).filter(Boolean);

if (linhas.length < 2) {
  return [{ json: { investimentos: [] } }];
}

const cabecalho = linhas[0].split(',').map(campo => campo.trim());
const investimentos = linhas.slice(1).map(linha => {
  const valores = linha.split(',').map(valor => valor.trim());
  return Object.fromEntries(cabecalho.map((campo, indice) => [campo, valores[indice] ?? '']));
});

return [{ json: { investimentos } }];

const entrada = items.map(item => item.json);
const clientes = entrada.flatMap(dado => dado.body?.clientes ?? dado.clientes ?? []);
const investimentos = entrada.flatMap(dado => dado.investimentos ?? []);

if (!clientes.length) {
  throw new Error('Nenhum cliente foi recebido no campo "clientes".');
}

const mensagens = {
  Conservador: [
    'Olá, {{nome}}! Para o seu perfil conservador, avalie alternativas de renda fixa compatíveis com seus objetivos e prazo.',
    'Olá, {{nome}}! Seu perfil valoriza segurança e estabilidade. Uma carteira de renda fixa pode ajudar na organização dos seus investimentos.',
    'Olá, {{nome}}! Para buscar mais previsibilidade, considere opções de renda fixa adequadas à sua tolerância a riscos.'
  ],
  Moderado: [
    'Olá, {{nome}}! Para o seu perfil moderado, uma combinação entre renda fixa e renda variável pode equilibrar segurança e crescimento.',
    'Olá, {{nome}}! Seu perfil permite diversificar entre investimentos mais estáveis e alternativas com maior potencial de retorno.',
    'Olá, {{nome}}! Uma carteira diversificada pode ajudar a distribuir os riscos e buscar oportunidades no longo prazo.'
  ],
  Arrojado: [
    'Olá, {{nome}}! Para o seu perfil arrojado, a renda variável pode oferecer maior potencial de retorno, acompanhada de maiores riscos.',
    'Olá, {{nome}}! Seu perfil aceita mais oscilações em busca de crescimento. Avalie alternativas de renda variável adequadas aos seus objetivos.',
    'Olá, {{nome}}! Uma exposição maior à renda variável pode fazer sentido, desde que você esteja preparado para oscilações e possíveis perdas.'
  ]
};

return clientes.map(cliente => {
  const perfil = cliente.perfil ?? 'Não informado';
  const opcoes = mensagens[perfil];
  const indice = opcoes ? Math.floor(Math.random() * opcoes.length) : 0;

  return {
    json: {
      nome: cliente.nome ?? '',
      email: cliente.email ?? '',
      saldo: cliente.saldo ?? '',
      perfil,
      investimentos_disponiveis: investimentos.filter(investimento =>
        Object.values(investimento).some(valor =>
          String(valor).toLowerCase().includes(perfil.toLowerCase())
        )
      ),
      mensagem: opcoes
        ? opcoes[indice].replace('{{nome}}', cliente.nome ?? 'cliente')
        : 'Perfil não identificado. É necessária uma nova análise antes da escolha de investimentos.'
    }
  };
});

