const entradasGPT = $input.all();
const clientesOriginais = $("Code - Gerar mensagens").all();

function obterTextoDoGPT(json) {
  const possiveisTextos = [
    // Formato mostrado na sua imagem
    json.output?.[0]?.content?.[0]?.text,

    // Outro formato possível do n8n
    json.output?.output?.[0]?.content?.[0]?.text,

    json.output_text,
    json.text,
    json.response
  ];

  const textoEncontrado = possiveisTextos.find(
    texto => typeof texto === "string" && texto.trim() !== ""
  );

  return textoEncontrado || "";
}

function limparResposta(texto) {
  let resposta = String(texto || "").trim();

  resposta = resposta
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  return resposta;
}

function interpretarJSON(texto) {
  if (!texto) {
    return {};
  }

  const textoLimpo = limparResposta(texto);

  // Primeira tentativa: JSON normal
  try {
    return JSON.parse(textoLimpo);
  } catch (erro) {
    // Continua para a próxima tentativa
  }

  // Segunda tentativa: JSON com aspas e quebras escapadas
  try {
    const textoCorrigido = textoLimpo
      .replace(/\\"/g, '"')
      .replace(/\\n/g, "\n");

    return JSON.parse(textoCorrigido);
  } catch (erro) {
    // Continua para a próxima tentativa
  }

  // Terceira tentativa: extrair somente o trecho entre { e }
  const inicioJSON = textoLimpo.indexOf("{");
  const fimJSON = textoLimpo.lastIndexOf("}");

  if (inicioJSON !== -1 && fimJSON !== -1) {
    const trechoJSON = textoLimpo.substring(
      inicioJSON,
      fimJSON + 1
    );

    try {
      return JSON.parse(trechoJSON);
    } catch (erro) {
      return {};
    }
  }

  return {};
}

function escaparHTML(texto) {
  return String(texto || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function transformarEmHTML(texto) {
  const textoEscapado = escaparHTML(texto);

  const paragrafos = textoEscapado
    .split(/\n\s*\n/)
    .filter(paragrafo => paragrafo.trim() !== "")
    .map(paragrafo => {
      return `<p>${paragrafo.replace(/\n/g, "<br>")}</p>`;
    })
    .join("\n");

  return `
<html>
  <body>
    ${paragrafos}

    <br>

    <p>
      <strong>Atenção:</strong> esta mensagem possui caráter educativo
      e não constitui recomendação financeira individual.
    </p>
  </body>
</html>
`.trim();
}

return entradasGPT.map((entrada, indice) => {
  const cliente = clientesOriginais[indice]?.json || {};

  const textoGPT = obterTextoDoGPT(entrada.json);
  const respostaGPT = interpretarJSON(textoGPT);

  const nome = cliente.nome || "cliente";
  const email = cliente.email || "";

  const assunto =
    respostaGPT.assunto ||
    respostaGPT.subject ||
    "Sugestão de investimento personalizada";

  const corpo =
    respostaGPT.corpo ||
    respostaGPT.body ||
    respostaGPT.text_body ||
    respostaGPT.mensagem ||
    textoGPT ||
    `Olá, ${nome}! Não foi possível gerar a mensagem personalizada.`;

  const corpoFinal = String(corpo)
    .replace(/\\n/g, "\n")
    .trim();

  return {
    json: {
      ok: Boolean(email && corpoFinal),

      to: email,

      subject: assunto,

      text_body: corpoFinal,

      html_body: transformarEmHTML(corpoFinal),

      meta: {
        nome: nome,
        email: email,
        perfil: cliente.perfil || "",
        saldo: cliente.saldo || "",
        quantidade_investimentos:
          cliente.investimentos_disponiveis?.length || 0
      }
    }
  };
});
